// Собрано tools/build-mind-data.mjs из mind-src/*.json. Руками не править.
export default {"intro":{"ageQ":"How old is your child?","ages":["3-5","6-8","9-12"],"genderQ":"Is your child a boy or a girl?","genders":["Boy","Girl"]},"questions":[{"id":"q1","text":"What does your child do when nobody is entertaining them?","options":[{"scale":"builder","text":"Builds or assembles something"},{"scale":"storyteller","text":"Makes up stories, gives the toys voices"},{"scale":"mover","text":"Runs, climbs, jumps"},{"scale":"artist","text":"Draws, sculpts, cuts things out"},{"scale":"inventor","text":"Takes things apart or tests \"what happens if…\""},{"scale":"explorer","text":"Looks closely, watches, searches and finds things"},{"scale":"leader","text":"Gathers others and starts a game for everyone"},{"scale":"helper","text":"Comes to help you or looks after someone"}]},{"id":"q2","text":"Which toys keep your child busy the longest?","options":[{"scale":"inventor","text":"Puzzles and experiment kits"},{"scale":"helper","text":"Dolls, stuffed animals, playing house or doctor"},{"scale":"leader","text":"Games with rules played with others"},{"scale":"explorer","text":"Finds from outside: stones, bugs, sticks"},{"scale":"builder","text":"Building sets and blocks"},{"scale":"storyteller","text":"Books, figures and toys for stories"},{"scale":"artist","text":"Paints, modeling clay, craft kits"},{"scale":"mover","text":"A ball, a scooter, a jump rope: anything for moving"}]},{"id":"q3","text":"What does your child ask \"why\" about most often?","options":[{"scale":"inventor","text":"How things and machines work"},{"scale":"explorer","text":"Animals, nature, space"},{"scale":"storyteller","text":"What words mean, how a story ends"},{"scale":"helper","text":"Why people feel sad, angry or happy"}]},{"id":"q4","text":"What does your child pick on a screen when the choice is theirs?","options":[{"scale":"builder","text":"Games where you build worlds and cities"},{"scale":"artist","text":"Drawing, music, craft videos"},{"scale":"mover","text":"Sports, dancing, tricks"},{"scale":"leader","text":"Competitions and challenges"}]},{"id":"q5","text":"What does your child do at the playground?","options":[{"scale":"mover","text":"Goes straight for the highest climb"},{"scale":"leader","text":"Gathers kids and sets up a game"},{"scale":"explorer","text":"Checks every corner and finds things"},{"scale":"helper","text":"Looks after younger kids, shares"}]},{"id":"q6","text":"Which books and stories does your child like?","options":[{"scale":"storyteller","text":"Tales and adventures with heroes"},{"scale":"inventor","text":"Fact books and \"how things work\""},{"scale":"artist","text":"Ones with beautiful pictures to study"},{"scale":"builder","text":"About vehicles, machines, construction sites"}]},{"id":"q7","text":"Which gift would your child choose?","options":[{"scale":"builder","text":"A construction set"},{"scale":"artist","text":"An art set or a musical instrument"},{"scale":"inventor","text":"A science kit"},{"scale":"mover","text":"A ball, scooter or bike"}]},{"id":"q8","text":"What makes your child most proud?","options":[{"scale":"leader","text":"Winning or being in charge"},{"scale":"helper","text":"Helping someone"},{"scale":"storyteller","text":"Performing, telling a story, making people laugh"},{"scale":"explorer","text":"Finding or discovering something new"}]},{"id":"q9","text":"A toy your child loves breaks. What do they do?","options":[{"scale":"builder","text":"Tries to fix it"},{"scale":"inventor","text":"Takes it apart to see what's inside"},{"scale":"artist","text":"Turns it into something else"},{"scale":"storyteller","text":"Makes up a story about what happened"}]},{"id":"q10","text":"A new group of kids. How does your child act?","options":[{"scale":"leader","text":"Suggests what to play"},{"scale":"helper","text":"Finds one child and makes friends"},{"scale":"explorer","text":"Watches and looks around first"},{"scale":"mover","text":"Jumps straight into the running around"}]},{"id":"q11","text":"A task isn't working out. What does your child do?","options":[{"scale":"inventor","text":"Tries a different way"},{"scale":"builder","text":"Goes step by step until it works"},{"scale":"leader","text":"Gets others to do it together"},{"scale":"storyteller","text":"Talks it through out loud"}]},{"id":"q12","text":"Your child loses a game. What happens next?","options":[{"scale":"mover","text":"Wants a rematch right now"},{"scale":"leader","text":"Argues about the rules, negotiates"},{"scale":"helper","text":"Congratulates, cares how others feel"},{"scale":"artist","text":"Goes off to do their own thing"}]},{"id":"q13","text":"A free day. What would your child choose?","options":[{"scale":"explorer","text":"Forest, zoo or museum"},{"scale":"mover","text":"Pool, trampolines, sports"},{"scale":"artist","text":"Crafting, drawing, music"},{"scale":"storyteller","text":"A play, a movie or books"}]},{"id":"q14","text":"Someone nearby is crying. What does your child do?","options":[{"scale":"helper","text":"Goes over to comfort them"},{"scale":"leader","text":"Fetches an adult, takes charge"},{"scale":"storyteller","text":"Asks what happened"},{"scale":"inventor","text":"Tries to fix the cause"}]},{"id":"q15","text":"You're packing for a trip. How does your child get ready?","options":[{"scale":"builder","text":"Packs things in order"},{"scale":"explorer","text":"Asks where you're going and what's there"},{"scale":"artist","text":"Picks an outfit and a few treasured little things"},{"scale":"mover","text":"Can't sit still, already at the door"}]},{"id":"q16","text":"Your child gets a box of random parts. What do they do?","options":[{"scale":"builder","text":"Builds something right away"},{"scale":"inventor","text":"Sorts them and tests what each does"},{"scale":"helper","text":"Thinks of a present to make for someone"},{"scale":"explorer","text":"Studies each one and asks where it's from"}]}],"sliders":{"labels":["Rarely","Sometimes","Often","Almost always","Always"],"items":[{"id":"energy","text":"My child prefers active play to sitting activities"},{"id":"boldness","text":"Approaches new places, people and activities with confidence"},{"id":"persistence","text":"Finishes what they start, even when it's hard"},{"id":"sensitivity","text":"Picks up on others' moods and feels things deeply"},{"id":"sociability","text":"Makes friends easily and loves being around people"},{"id":"pace","text":"Likes things fast and doesn't like waiting"}]},"goal":{"text":"What do you most want to find out?","options":[{"id":"activity","text":"Which club or activity to choose"},{"id":"strengths","text":"What my child is strongest at"},{"id":"future","text":"What to try next with my child"},{"id":"character","text":"How to get through to my child"}]},"types":{"builder":{"name":"Builder","nameF":"Builder","tagline":"Thinks with their hands and sees how parts make a whole","careers":"engineer, architect, mechanic, carpenter"},"inventor":{"name":"Inventor","nameF":"Inventor","tagline":"Wants to know how everything works and tries it their own way","careers":"scientist, software developer, analyst, medical researcher"},"storyteller":{"name":"Storyteller","nameF":"Storyteller","tagline":"Thinks in words and stories and draws others in","careers":"journalist, writer, lawyer, actor"},"artist":{"name":"Artist","nameF":"Artist","tagline":"Notices beauty and detail and creates something of their own","careers":"designer, illustrator, musician, architect"},"explorer":{"name":"Explorer","nameF":"Explorer","tagline":"Observes, collects facts and goes to see what's around the corner","careers":"biologist, vet, geographer, environmental scientist"},"leader":{"name":"Leader","nameF":"Leader","tagline":"Takes the initiative, negotiates and brings others along","careers":"entrepreneur, manager, event planner, coach"},"helper":{"name":"Helper","nameF":"Helper","tagline":"Senses how others feel and is first to help","careers":"doctor, teacher, psychologist, vet"},"mover":{"name":"Mover","nameF":"Mover","tagline":"Thinks on the move: tries it with their body first, explains later","careers":"athlete, coach, choreographer, rescue worker"}},"shade":{"swift":{"m":"swift","f":"swift"},"calm":{"m":"thoughtful","f":"thoughtful"}},"disclaimer":"Based on a parent's observations. Not a psychological or medical assessment.","report":{"builder":{"about":"{name} thinks with their hands. Things make sense once they have built them, taken them apart or put them together. They see how parts become a whole and keep going until the structure stands.","hooks":"Pulls them in: tasks with a clear result you can touch. Gets boring fast: long explanations with nothing to do and activities with nothing to build.","strengths":["Spatial thinking: can picture how pieces will fit","Patience for step-by-step work","Gets things to a working result"],"grow":"Worth supporting: putting into words what they are doing and why. Ask for a guided tour of what they built.","say":["\"Tell me how you figured this out\"","\"What was the hardest part of building this?\"","\"What would you change next time?\""],"ages":{"3-5":"large building blocks, sand and water play, cardboard-box builds","6-8":"instruction-based building sets, origami, simple models, beginner robotics","9-12":"model making, a 3D pen or 3D design app, a woodworking or maker workshop"},"plan":["Week 1. Build from a plan: one model from instructions, start to finish.","Week 2. Their own version: change the model to make it better.","Week 3. A challenge with limits: a paper bridge that holds a book.","Week 4. A family project: make something useful for the home and present it."]},"inventor":{"about":"{name} wants to know how everything works and has to test it for themselves. A ready answer interests them less than their own experiment. They try, get it wrong and try another way.","hooks":"Pulls them in: puzzles, experiments, the question \"what happens if…\". Gets boring fast: repeating the same thing and doing it \"because that's the rule\".","strengths":["Curiosity and sharp questions","Logic: sees cause and effect","Unafraid of mistakes, looks for another way"],"grow":"Worth supporting: finishing. They have more ideas than finished projects. Agree on one small finish line at a time.","say":["\"How could you test that?\"","\"Great question, let's find out together\"","\"A mistake is a result too. What did it show you?\""],"ages":{"3-5":"water play and large fridge magnets, sorting games, simple puzzles","6-8":"science kits, chess, logic games, first steps in coding","9-12":"coding, electronics, a science club, problem-solving competitions"},"plan":["Week 1. One 10-minute experiment a day: what sinks, what sticks to a magnet, what dissolves.","Week 2. An \"I thought… but it turned out…\" journal: a guess before, the result after.","Week 3. Logic: one game or puzzle, a little harder each day.","Week 4. Their own experiment: pick a question, test it and present it to the family."]},"storyteller":{"about":"{name} thinks in words and stories. They remember what is told as a story and turn an ordinary day into one. Being listened to matters to them.","hooks":"Pulls them in: books, conversations, role play, performing. Gets boring fast: silent solo work and tasks with no story or characters.","strengths":["Rich language and a memory for stories","Imagination: invents worlds and characters","Can captivate and persuade"],"grow":"Worth supporting: listening as willingly as talking. Play \"interviewer\", where they ask the questions.","say":["\"Tell me what happened next\"","\"I love the word you chose there\"","\"How did the character feel?\""],"ages":{"3-5":"reading aloud with questions, puppet shows, making up bedtime stories","6-8":"drama club, making a comic or a little book, a foreign language","9-12":"debate club, a school paper or blog, creative writing or theater"},"plan":["Week 1. Story of the day: three sentences each evening about the main event.","Week 2. Their own book: 6 pages with pictures and text.","Week 3. An interview: ask a grandparent, neighbor or friend and retell it.","Week 4. A performance: present the story to the family, with roles or puppets."]},"artist":{"about":"{name} notices what others miss: color, shape, sound, mood. They think in images and want to do it their own way, not like the example.","hooks":"Pulls them in: freedom to choose the material and the result. Gets boring fast: paint-by-numbers tasks, rushing and being judged right or wrong.","strengths":["A sharp eye for detail","Original ideas","Can stay absorbed in their work for a long time"],"grow":"Worth supporting: showing work to others and taking comments calmly. Start with \"what do you like about it yourself?\"","say":["\"Tell me what's happening here\"","\"I can see how much work went into these details\"","\"How did you choose these colors?\""],"ages":{"3-5":"paints and finger painting, modeling clay, music and dancing to it","6-8":"art classes, a musical instrument, crafts from everyday materials","9-12":"drawing or digital illustration, photo and video, a band or choir"},"plan":["Week 1. One material a day: pencil, paint, clay, paper, things from nature.","Week 2. One theme, five ways: draw it, sculpt it, photograph it, collage it, act it out.","Week 3. A big piece: one project for the whole week, 15 minutes a day.","Week 4. A home exhibition: choose the best pieces, label them and invite the family."]},"explorer":{"about":"{name} looks first and acts second. They collect facts, spot patterns and remember amazing details about animals, planets or dinosaurs.","hooks":"Pulls them in: anything new, living and real, collections and maps. Gets boring fast: staying indoors and learning what they can't see.","strengths":["Powers of observation","A memory for facts and details","Independence: can keep themselves busy"],"grow":"Worth supporting: joining a new group. They need time to look around. Don't rush them, give them 10 minutes to watch.","say":["\"What did you notice today that was new?\"","\"Show me what you found\"","\"Let's check if that's true\""],"ages":{"3-5":"walks with a magnifying glass, caring for a plant, animal books","6-8":"a nature club, collections, scouts, hiking","9-12":"biology or astronomy, orienteering, volunteering at an animal shelter"},"plan":["Week 1. Discovery walks: find three new things each day on a familiar route.","Week 2. A collection: gather, sort and label 10 finds.","Week 3. Observation: one subject for a week (a plant, birds, the weather) with a daily note.","Week 4. An expedition: plan a family outing and act as the guide."]},"leader":{"about":"{name} quickly sees what needs doing and gets people together to do it. They suggest the rules, hand out roles and care about the shared result.","hooks":"Pulls them in: a goal, a team and a say in decisions. Gets boring fast: tasks with no choice and situations where nothing depends on them.","strengths":["Initiative: goes first","Can negotiate","Takes responsibility for the outcome"],"grow":"Worth supporting: giving way and losing. Sometimes give them the \"first mate\" role, with someone else in charge.","say":["\"How did you decide who does what?\"","\"What do the others think? Ask them\"","\"Today this one is yours to run\""],"ages":{"3-5":"games with rules, being the \"helper of the day\" at home, simple team games","6-8":"team sports, strategy board games, scouts","9-12":"team captain, student council, a small project or stand of their own"},"plan":["Week 1. One job at home that is fully theirs for the week.","Week 2. Family game night: they explain the rules and run the game.","Week 3. A mini project: organize an outing or a party for two or three people.","Week 4. Switching roles: a week of helping and following someone else's plan."]},"helper":{"about":"{name} reads people's moods before they say a word. Relationships matter to them: they remember who likes what and try to make sure everyone is okay.","hooks":"Pulls them in: doing things with someone and for someone. Gets boring fast: rivalry and activities where everyone is on their own.","strengths":["Empathy: understands how others feel","Reliability and care","Good at making peace and bringing people together"],"grow":"Worth supporting: saying no and naming what they want. Ask more often, \"and what do you want?\"","say":["\"You noticed someone was sad. That matters\"","\"And what would you like?\"","\"You can say no and still be a good friend\""],"ages":{"3-5":"playing house and vet, caring for a pet or plant, helping in the kitchen","6-8":"small-group clubs, looking after animals, first aid for kids","9-12":"volunteering, mentoring younger kids, psychology or biology"},"plan":["Week 1. One kind act a day and a short evening chat about how it went.","Week 2. Caring for something living: watering a plant or feeding a pet becomes their daily job, with you checking.","Week 3. My wishes: one choice each day is theirs alone (dinner, the game, the route).","Week 4. A handmade gift: plan and make one for someone close."]},"mover":{"about":"{name} thinks on the move. Understanding and remembering come easier when the body joins in: show it, try it, do it again. They have more energy than an ordinary day asks for.","hooks":"Pulls them in: speed, a challenge, new tricks. Gets boring fast: sitting and listening for a long time with no chance to get up.","strengths":["Coordination and agility","Courage to try new things","Persistence when practicing a skill"],"grow":"Worth supporting: quiet activities. Let them move first: 10 active minutes make sitting still easier afterwards.","say":["\"Show me how you do it\"","\"I saw how many times you tried before it worked\"","\"Run around first, then we'll sit down\""],"ages":{"3-5":"a balance bike, a home obstacle course, swimming, dancing","6-8":"gymnastics, swimming, team games, martial arts","9-12":"a club in their chosen sport, climbing, a dance crew"},"plan":["Week 1. 10 minutes of movement a day: one new game or exercise.","Week 2. One skill: pick a trick (jump rope, a balance, a ball skill) and practice all week.","Week 3. A tryout: one trial session at a new club.","Week 4. Re-check: take the movement test again and compare with the first result."],"extra":"This type's report has a \"Check physical strengths\" button: 3 minutes of exercises in front of the phone camera."}},"cards":[{"id":"builder-1","scale":"builder","art":"📄🌉🧸","title":"Paper bridge","task":{"3-5":"Lay a sheet of paper between two books. How many toys can it hold? Fold the sheet like a fan and test again.","6-8":"Build a bridge from one sheet of paper between two books. The goal: it holds 10 coins. No tape, no scissors.","9-12":"Three sheets of paper and tape. Build a 12-inch (30 cm) bridge that holds a book. Sketch a plan first, then compare it with what you built."},"why":"Your child sees firsthand that shape can make a weak material strong. That is the heart of engineering thinking.","tip":"Don’t give the answer. Ask: “Why do you think it sagged? What could we change?”","need":{"3-5":"a sheet of paper, two books, 5–6 light toys","6-8":"a sheet of paper, two books, 10 coins or erasers","9-12":"three sheets of paper, tape, a ruler, a book"},"steps":{"3-5":["Put the books side by side, an adult’s hand apart, and lay the sheet across like a bridge.","Place toys on the bridge one at a time and count out loud how many it holds.","Fold the sheet like a fan together and lay it down again.","Test again and compare: how many toys before, how many now?"],"6-8":["The challenge: a bridge made from one sheet must hold 10 coins. No tape, no scissors.","First try: your child lays the sheet flat and tests it.","Give 3 minutes to experiment: bending, folding and rolling are all allowed.","Test the best version and ask your child to explain why it holds."],"9-12":["The rule: a 12-inch (30 cm) bridge must hold a book.","First your child sketches a plan: what shape, where the supports go.","Build to the plan, 5 minutes.","Test with the book. Compare plan and result: what had to change, and why?"]}},{"id":"builder-2","scale":"builder","art":"🧱🗼📏","title":"Tallest tower","task":{"3-5":"Build a tower of blocks or plastic cups taller than your child's knee. Then taller than their waist.","6-8":"Take 20 kitchen items (cups, sponges, boxes). Build a tower taller than the table. Did it fall? Find the floor that failed.","9-12":"A tower from paper and tape only, not leaning on a wall. Target: 3 feet (1 m). Measure it, write down the record, try to beat it."},"why":"A tower teaches balance, patience and how to find the mistake: not “everything” fell, one level gave way.","tip":"When the tower falls, don’t comfort right away. Ask: “Which level gave way?”","need":{"3-5":"blocks or plastic cups","6-8":"20 kitchen items: cups, sponges, boxes","9-12":"paper, tape, a tape measure"},"steps":{"3-5":["Build a tower together that is taller than your child’s knee.","Now aim higher: up to the waist. Your child builds, you hand over the pieces.","If it falls, look together at where it wobbled.","Build again with a wide base and compare."],"6-8":["Lay the items out and give your child a minute to look them over.","The challenge: a tower taller than the table. Your child builds.","Did it fall? Find the level that gave way and swap it.","Measure the finished tower in hand spans and remember the record."],"9-12":["The rule: paper and tape only, no leaning on the wall. The goal: 3 feet (1 m).","Your child picks the shape of the supports: tubes, triangles or fan folds.","Build for 7 minutes, then measure.","Write down the record and one idea for beating it next time."]}},{"id":"builder-3","scale":"builder","art":"📦🏠🧸","title":"A house for a toy","task":{"3-5":"Make a house for a favorite toy from a box and cushions. Where is the door? Where is the bed?","6-8":"Build a toy house from a box: a door that opens and a window. An adult does the cutting.","9-12":"Design a box house: first a drawing with measurements, then the build. It needs two floors and a staircase."},"why":"Your child plans a space: what goes where, and why. This builds the habit of thinking first and building second.","tip":"Ask questions as the toy: “Where will I sleep? How do I get in?”","need":{"3-5":"a box, pillows, a favorite toy","6-8":"a box, markers, tape, scissors (the adult cuts)","9-12":"a box, a ruler, paper, tape, scissors"},"steps":{"3-5":["Ask: what kind of house does the toy need? Big or small?","Build the walls from pillows and the box.","Decide together where the door is and where the bed goes.","Move the toy in and wish it good night."],"6-8":["Your child marks where the door and the window will be.","The adult cuts along the lines and leaves one side of the door attached so it opens.","Your child decorates the house: walls, a rug, furniture from small boxes.","A house tour: your child shows you around and explains."],"9-12":["Start with a drawing: two floors and stairs, with measurements.","Your child marks out the parts with the ruler.","Assembly. The adult cuts the sharp and stiff parts.","Check the house against the drawing: what matched, what had to change?"]}},{"id":"builder-4","scale":"builder","art":"🛝⚽🚗","title":"Marble run","task":{"3-5":"Make a ramp from cardboard or a book. Roll a ball down. Which is faster: the ball or a toy car?","6-8":"Build a ball track from cardboard tubes and tape on a wall or door. The ball must travel for at least 5 seconds.","9-12":"A ball track with three turns and a cup at the finish. Time it. The goal: make the run slower without the ball stopping."},"why":"An experiment with slope and speed: your child changes one thing and sees the result right away.","tip":"Ask for a prediction before every run: “Which one do you think will be faster?”","need":{"3-5":"a piece of cardboard or a big book, a ball, a toy car","6-8":"cardboard tubes from paper rolls, masking tape, a small ball or a ball of foil","9-12":"tubes, cardboard, tape, a cup, a stopwatch"},"steps":{"3-5":["Make a ramp: rest one edge of the cardboard on the couch or a stack of books.","Roll the ball, then the car. Which got there faster?","Raise the edge higher and test again.","Let your child choose what to roll third."],"6-8":["Tape the first tube to a door or wall at a slant.","Your child adds the next ones so the ball passes from one into another.","Run it after every new piece and adjust.","The goal: the ball travels for at least 5 seconds. Count out loud."],"9-12":["The rule: three turns and a finish inside the cup.","Your child builds the track and does a trial run.","Time it. New challenge: make the run slower, but the ball must not stop.","Write down the time before and after, and what exactly was changed."]}},{"id":"builder-5","scale":"builder","art":"🔧🪛🚪","title":"Fix it with me","task":{"3-5":"Let your child screw on a big lid, zip up a zipper or close a snap. Let them finish it on their own.","6-8":"Find something at home that needs tightening or gluing. Your child does it, you only give hints.","9-12":"Pick a small thing at home that needs fixing. Your child works out the cause, suggests a method and fixes it. You look after safety."},"why":"Your child feels that their own hands can fix a real thing. That builds more confidence than any praise.","tip":"Keep your hands behind your back. Help with words, not with your hands.","need":{"3-5":"a jar with a big lid, a jacket with a zipper, shoes with Velcro","6-8":"something that needs tightening or gluing, a screwdriver or glue","9-12":"a small household repair, the right tools"},"steps":{"3-5":["Show once, slowly, how the lid screws on.","Your child screws it on all the way alone.","Same with the zipper and the Velcro.","Say exactly what worked: “You zipped it all the way to the top yourself.”"],"6-8":["Find together what has come loose or unstuck at home.","Your child looks it over and says what is wrong with it.","Your child does the repair, you only give hints.","Check together: does it hold?"],"9-12":["Pick one problem together: a squeaky cabinet door, a wobbly handle.","Your child finds the cause and suggests a fix.","You check that it is safe, and your child does the repair.","A day later, check whether the repair is holding."]}},{"id":"inventor-1","scale":"inventor","art":"💧🍎⛵","title":"Sink or float","task":{"3-5":"A bowl of water and 6 large objects. Before each one ask: will it sink or float? Then test it. Stay beside the water and empty the bowl afterwards.","6-8":"10 objects. Your child writes a guess for each, then tests. How many were right? What do the floating ones have in common?","9-12":"Make a foil boat that carries the most coins. Three tries with different shapes. Which shape won, and why?"},"why":"Prediction, test, conclusion: your child walks a scientist’s path in miniature.","tip":"If the prediction was wrong, be delighted: “That’s a surprise! Why did that happen?”","need":{"3-5":"a tub of water, 6 large items: a sponge, a spoon, a plastic lid, an apple, a ball, a wooden block","6-8":"a tub of water, 10 items, paper and a pencil","9-12":"foil, a tub of water, coins"},"steps":{"3-5":["Before each item, ask: will it sink or float?","Your child lowers the item into the water.","Sort into two sides: what floats and what sinks.","Stay close the whole time. Pour the water out as soon as you finish."],"6-8":["Your child writes or draws a prediction for each item.","Tests them one by one and marks a plus or a minus.","Count how many predictions were right.","Ask: what do the floating ones have in common?"],"9-12":["The challenge: a foil boat that holds the most coins.","Three tries with different shapes: flat, with sides, long.","For each one, count the coins until it sinks.","Which shape won, and why? Write the answer in one sentence."]}},{"id":"inventor-2","scale":"inventor","art":"🥛🧂🔍","title":"What happens if","task":{"3-5":"Mix water with what you have in the kitchen: salt, sugar, flour, oil. What disappears and what doesn't? Nothing here is for tasting.","6-8":"Baking soda and vinegar in a glass. Guess first, then test. What changes if you double the baking soda?","9-12":"Think up your own \"what happens if…\" question about water, ice or a magnet. Write a guess, run the test, write the result."},"why":"Your child learns to change one thing and watch what happens. Every experiment works this way.","tip":"Instead of explaining, ask: “What if we use more? What if it’s warmer?”","need":{"3-5":"4 glasses of water, a spoon, salt, sugar, flour, cooking oil","6-8":"a glass, a tray, baking soda, vinegar, a spoon","9-12":"water, ice or a magnet, your choice; paper for notes"},"steps":{"3-5":["Your child adds a spoonful of one ingredient to each glass.","Stir and look: what disappeared and what didn’t?","Find the glass where the most interesting thing happened.","No tasting needed. Pour everything out together afterwards."],"6-8":["Put the glass on the tray. Your child predicts: what will happen?","Add a spoonful of baking soda; the adult pours the vinegar.","Repeat with two spoonfuls of baking soda.","What changed? Your child explains in their own words."],"9-12":["Your child comes up with their own “what happens if…” question.","Writes down a prediction.","Runs the experiment. You watch over safety.","Writes down the result and compares it with the prediction."]}},{"id":"inventor-3","scale":"inventor","art":"📦💡♻️","title":"A new job for an old thing","task":{"3-5":"Take an empty box. What could it be? Think of three ideas and play each one.","6-8":"One clothespin. Think of 10 ways to use it other than hanging laundry. Try the best one for real.","9-12":"Pick something you were about to throw away. Invent a useful object for the home from it and make it."},"why":"The habit of seeing many possibilities in an ordinary thing. That is where inventiveness starts.","tip":"Accept every idea, even the odd ones. You’ll choose later.","need":{"3-5":"an empty box","6-8":"one clothespin, a sheet of paper","9-12":"something you were going to throw away, glue, tape, scissors"},"steps":{"3-5":["Ask: what could this box be?","Come up with three ideas: a car, a house, a hat.","Play each one for a minute.","Which idea was the favorite?"],"6-8":["The challenge: 10 ways to use a clothespin, other than hanging laundry.","Your child calls them out, you write. The first ideas will be simple, later ones get more interesting.","Pick the best one together.","Try it out for real."],"9-12":["Pick a thing: a jar, a box, an old T-shirt.","Your child decides what useful household item it will become.","Makes it. You help only where a tool is needed.","Find a place for it and use it for a week."]}},{"id":"inventor-4","scale":"inventor","art":"🥄🍴🔢","title":"Find the pattern","task":{"3-5":"Lay out a row: spoon, fork, spoon, fork. What comes next? Then your child makes up a row.","6-8":"Write a row of numbers: 2, 4, 6, 8. What's next? Then 1, 2, 4, 7, 11. Then your child sets a row for you.","9-12":"Your child invents a code (letter = number or symbol) and writes you a note. Your job: crack it. Then swap."},"why":"Spotting the rule in a sequence is a skill for math, music and coding.","tip":"When your child sets a sequence for you, get it wrong once on purpose. Let them explain the rule.","need":{"3-5":"4 spoons and 4 forks (or blocks in two colors)","6-8":"a sheet of paper, a pencil","9-12":"paper, a pen"},"steps":{"3-5":["Lay out a row: spoon, fork, spoon, fork.","Ask: what comes next? Your child adds the next item.","Make it harder: two spoons, one fork.","Now your child makes up the row and you continue it."],"6-8":["Write a sequence: 2, 4, 6, 8. What comes next?","Then a harder one: 1, 2, 4, 7, 11.","Ask your child to explain the rule in words.","Your child sets a sequence for you."],"9-12":["Your child invents a code: each letter is a number or a symbol.","Writes you a one-sentence note.","You decode it. Ask for the key only after three tries.","Swap roles."]}},{"id":"inventor-5","scale":"inventor","art":"⚙️🔗🔔","title":"A machine for a simple job","task":{"3-5":"How can you get a toy off a shelf without standing up? Try a string, a spoon, a stick. What worked?","6-8":"Invent and draw a machine that feeds the cat or waters a plant. Label what each part does.","9-12":"Build a 4-step chain reaction: dominoes push a ball, the ball drops into a cup and so on. The goal: a bell rings or a spoon falls at the end."},"why":"Your child breaks a problem into steps and links them into a chain. That is engineering and logic working together.","tip":"Don’t fix the machine yourself. Ask: “At which step did it stop?”","need":{"3-5":"a toy on a low shelf, a string, a big spoon, a stick","6-8":"a sheet of paper, pencils","9-12":"dominoes, a marble, a cup, books, a spoon or a bell"},"steps":{"3-5":["The challenge: get the toy without standing up from the floor.","Try the string, the spoon and the stick in turn.","What worked best?","Think of one more way together."],"6-8":["The challenge: invent a machine that feeds the cat or waters a plant.","Your child draws the whole thing.","Labels what each part does.","Tells you how it works, from start to finish."],"9-12":["The challenge: a 4-step chain reaction that ends with a bell ringing or a spoon falling.","Your child builds it and tests each step separately.","Run the whole thing. Didn’t work? Find the step where it stopped.","Film a successful run on a phone."]}},{"id":"storyteller-1","scale":"storyteller","art":"🧸📖✨","title":"A story from three things","task":{"3-5":"Take three toys. Start with \"Once upon a time…\". Your child says what happened next.","6-8":"Three random objects from the room. Your child makes up a story where all three matter. It has a beginning, a problem and an end.","9-12":"Three random words from a book. In 10 minutes your child writes a half-page story with a surprise ending and reads it aloud."},"why":"Your child builds a plot: a beginning, a problem, an ending. That is the basis of clear speaking and writing.","tip":"Don’t correct the plot. Help with a question: “And what happened next?”","need":{"3-5":"three toys","6-8":"three random things from the room","9-12":"a book, a sheet of paper, a pen, a timer"},"steps":{"3-5":["Put three toys in front of your child.","Start with “Once upon a time…” and name the first toy.","Your child says what happened next. Take turns adding one sentence each.","Finish together: how did it all end?"],"6-8":["With eyes closed, your child picks three things.","The rule: all three matter in the story.","The story has a beginning, a problem and an ending. Your child tells it out loud.","Retell the story back in two sentences: did you get it right?"],"9-12":["Open the book at random three times and write down one word each time.","In 10 minutes your child writes a half-page story using those words.","The rule: a surprise ending.","Your child reads it aloud. Say where it got interesting for you."]}},{"id":"storyteller-2","scale":"storyteller","art":"📚🐺🔀","title":"A different ending","task":{"3-5":"Read a familiar tale and stop before the end. Ask: how else could it end?","6-8":"Your child retells a favorite tale, but the villain turns out to be kind. What changes?","9-12":"Your child retells a well-known story as a minor character. What did that character see, and what didn't they know?"},"why":"To change a familiar plot, you have to understand how it works. This builds flexible thinking.","tip":"Ask “why did he do that?” rather than “was that right?”","need":{"3-5":"a familiar fairy-tale book","6-8":"nothing needed","9-12":"nothing needed"},"steps":{"3-5":["Read the story and stop just before the end.","Ask: how else could it end?","Accept any answer and carry it on with one sentence.","Read the real ending. Which one do you like more?"],"6-8":["Your child picks a favorite fairy tale.","The rule: the villain is actually kind.","Your child retells the tale with that change.","Talk about it: what changed for the other characters?"],"9-12":["Pick a well-known story, book or movie.","Your child chooses a minor character.","Retells the events in that character’s voice: what they saw and what they didn’t know.","Ask: who is the hero in this version?"]}},{"id":"storyteller-3","scale":"storyteller","art":"🎤👵❓","title":"The interview","task":{"3-5":"With a \"microphone\" (a spoon), your child asks you: what did you love when you were little?","6-8":"Your child prepares 5 questions for a grandparent or for you about childhood and does the interview. Then tells you what surprised them.","9-12":"Your child interviews an adult about their job: 7 questions, none answered with yes or no. Then sums up the main points in one minute."},"why":"Your child learns to ask questions and listen to the answer. That is half of knowing how to talk with people.","tip":"Answer seriously and briefly. Your child runs the interview, not you.","need":{"3-5":"a big spoon as a microphone","6-8":"a sheet of paper, a pencil; a grandparent or you","9-12":"a notebook, a pen, an adult with an interesting job"},"steps":{"3-5":["Hand your child the “microphone”.","They ask: what did you like to do when you were little?","Answer with one short story.","Swap: now you ask the question."],"6-8":["Your child prepares 5 questions about childhood.","Does the interview in person or by phone.","Drawing or writing down the main points is welcome.","Afterwards tells you what was most surprising."],"9-12":["Your child prepares 7 questions about the job. The rule: none can be answered with “yes” or “no”.","Does the interview and takes notes.","Sums up the main points for you in one minute.","Ask: which question worked best?"]}},{"id":"storyteller-4","scale":"storyteller","art":"🔤😄💬","title":"New words","task":{"3-5":"Make up a funny name for each toy together and explain why it is called that.","6-8":"Invent a word that doesn't exist and decide what it means. Use it three times in conversation today.","9-12":"Pick three unfamiliar words in a book. Your child guesses the meaning from the text first, then checks and uses each in a sentence."},"why":"Playing with words grows vocabulary and shows that language can be invented, not just learned.","tip":"Use the new word yourself. Your child needs to hear it in your speech.","need":{"3-5":"3–4 toys","6-8":"nothing needed","9-12":"a book, a sheet of paper"},"steps":{"3-5":["Pick up the first toy and give it a funny name.","Your child explains why it’s called that.","Your child names the next toy.","Introduce the toys to each other by their new names."],"6-8":["Make up a word together that doesn’t exist.","Agree on what it means.","Today’s challenge: use it three times in conversation.","In the evening, count who remembered it how many times."],"9-12":["Your child finds three unfamiliar words in a book.","First guesses the meaning from the sentences around them.","Checks in a dictionary or with you.","Writes a sentence of their own with each word."]}},{"id":"storyteller-5","scale":"storyteller","art":"📺🎙️🪟","title":"Live report","task":{"3-5":"Your child tells you what they see out of the window like a TV reporter: \"Here comes a red car…\"","6-8":"Your child gives a one-minute report from dinner or a walk: who, what, where. Record it on a phone and listen back.","9-12":"Your child prepares a two-minute family news show for the week: three stories and a weekend forecast. Record it and share it with family."},"why":"Your child describes what they see, in order and clearly for a listener. That is a presentation skill.","tip":"Be the audience: listen to the end and ask one question “from the studio”.","need":{"3-5":"a window","6-8":"a phone for recording (optional)","9-12":"a sheet of paper, a phone for recording"},"steps":{"3-5":["Sit by the window together.","Show how in a news-anchor voice: “Here comes a red car…”","Now your child reports, for one minute.","Thank your “reporter” and ask what was the most interesting."],"6-8":["The topic: dinner or a walk.","Your child talks for a minute: who, what, where.","Record it on the phone.","Listen together. What would they add next time?"],"9-12":["Your child picks three family news stories from the week.","Adds a forecast for the weekend.","Records a two-minute broadcast.","Show the recording to the family."]}},{"id":"artist-1","scale":"artist","art":"✏️🌀🐾","title":"The scribble drawing","task":{"3-5":"Draw a scribble. Your child turns it into an animal: adds eyes, paws, a tail.","6-8":"Each of you draws a scribble and hands it over. The task: turn the other person's scribble into a picture and give it a title.","9-12":"Five random lines on a page. Your child turns them into a finished drawing where no line is left over."},"why":"Your child learns to see an image in a random shape. That is how an artist’s or designer’s imagination works.","tip":"Ask “what did you see here?” rather than “what is it?”","need":{"3-5":"a sheet of paper, thick markers or crayons","6-8":"two sheets, markers","9-12":"a sheet of paper, a pencil or a pen"},"steps":{"3-5":["Draw one scribble on the sheet.","Ask: who does it look like?","Your child adds eyes, paws, a tail.","Give the creature a name."],"6-8":["Each of you draws a scribble on your own sheet.","Swap sheets.","The challenge: turn the other person’s scribble into a picture.","Give the pictures titles and show each other."],"9-12":["Draw five random lines on the sheet.","Your child turns them into a finished drawing.","The rule: no line is left over.","Ask them to show what each line became."]}},{"id":"artist-2","scale":"artist","art":"🎨🔵🖌️","title":"One color","task":{"3-5":"Name a color. Collect everything of that color around the home and lay out a picture on the floor.","6-8":"Paint a picture with only one color and its shades. How do you show night if all you have is blue?","9-12":"Take phone photos of 7 objects of one color so that the shots look like a series. Pick the best frame and explain why."},"why":"Working with a single color makes you look for shades and shapes. That trains the eye.","tip":"Point out the shades: “Look, this blue is darker. Where could it be useful?”","need":{"3-5":"things of one color from around the house","6-8":"a sheet of paper, paints or pencils in one color, water","9-12":"a phone with a camera"},"steps":{"3-5":["Name the color of the day.","Gather everything of that color at home: toys, socks, lids.","Lay the finds out as a picture on the floor.","Take a photo and put everything back together."],"6-8":["Your child picks one color.","The challenge: paint a picture with only that color and its shades.","Ask: how do you show night if you only have blue?","Find the lightest and the darkest spot in the picture."],"9-12":["Your child picks a color.","Takes photos of 7 things in that color so the shots look like a series.","Chooses the best shot.","Explains why that one."]}},{"id":"artist-3","scale":"artist","art":"🎵🖍️🌈","title":"Music on paper","task":{"3-5":"Play a fast song, then a slow one. Your child draws to each. How are the drawings different?","6-8":"Play music without words. Your child draws what they hear: lines, blobs, colors. Then tells you where the drawing is loud.","9-12":"Two different tracks, two sheets. Your child shows the mood of each with shape and color only, no objects. You guess which is which."},"why":"Your child turns sound into line and color. That connects hearing, feeling and the hand.","tip":"Don’t ask for objects. Here it’s about lines, patches and mood.","need":{"3-5":"two sheets of paper, crayons, two songs: a fast one and a slow one","6-8":"a sheet of paper, paints or markers, music without words","9-12":"two sheets, paints or pencils, two different tracks"},"steps":{"3-5":["Play the fast song. Your child draws to it on the first sheet.","Play the slow one. Second sheet.","Put the drawings side by side.","How are they different? Point with a finger."],"6-8":["Play music without words.","Your child draws what they hear: lines, patches, colors.","After the music, ask: where is it loud in the drawing, and where is it quiet?","Give the drawing a title."],"9-12":["Your child listens to the first track and shows its mood with shape and color only, no objects.","Same with the second track.","You guess which sheet goes with which track.","Your child explains their color choices."]}},{"id":"artist-4","scale":"artist","art":"🍂🌰🖼️","title":"Found-object picture","task":{"3-5":"Collect leaves, sticks and pine cones on a walk. At home, lay out a face or an animal from them.","6-8":"A collage from an old magazine and things found on a walk. Theme: \"a place I'd like to be\".","9-12":"Arrange objects on a table like a still life. Move a lamp around: how does light change the picture? Photograph the best version."},"why":"Arranging ready-made objects teaches your child to notice shape, texture and how things go together.","tip":"Ask: “What happens if we move this over here?” and let them try.","need":{"3-5":"leaves, sticks and pinecones from a walk, a sheet of paper","6-8":"an old magazine, finds from a walk, glue, a sheet of paper, scissors","9-12":"3–5 objects, a desk lamp, a phone"},"steps":{"3-5":["Collect leaves, sticks and pinecones on a walk.","At home, spread the finds out on the table.","Make a face or an animal together.","Take a photo. Wash hands after playing."],"6-8":["The theme: a place I’d like to be.","Your child cuts or tears pictures out of the magazine.","First arranges them on the sheet, then glues.","Tells you what this place is."],"9-12":["Your child arranges objects on the table like a still life.","Moves the lamp: from the side, from above, from behind.","Watches how the shadows and the mood change.","Photographs the best version."]}},{"id":"artist-5","scale":"artist","art":"🥔🟣💌","title":"My own pattern","task":{"3-5":"Print with paint using fingers, a sponge or half a potato. You get a pattern for a card.","6-8":"Design a pattern for your own T-shirt or mug and draw it on paper at full size.","9-12":"Design a logo for your family: three sketches, one final. Explain what each detail means."},"why":"A repeating pattern teaches rhythm and care, and a symbol teaches how to express an idea briefly.","tip":"Hang the finished work where everyone can see it. To a child that means more than words.","need":{"3-5":"finger paint, a sponge, half a potato, a sheet of paper, a table cover","6-8":"a sheet of paper, markers","9-12":"paper, a pencil, markers"},"steps":{"3-5":["Cover the table.","Show how to print with a finger, the sponge, the potato.","Your child prints a pattern all over the sheet.","When it’s dry, fold the sheet in half: you have a card."],"6-8":["Your child chooses: a pattern for a T-shirt or for a mug.","Draws the outline on the sheet at real size.","Fills it with a pattern.","Ask: who would they give it to?"],"9-12":["The challenge: a symbol for your family.","Three quick sketches, a minute each.","Your child picks one and draws the final version.","Explains what each detail means."]}},{"id":"explorer-1","scale":"explorer","art":"🔎🍃🪣","title":"Scavenger hunt","task":{"3-5":"On a walk, find: something round, something soft, something yellow, something noisy.","6-8":"A list of 8 finds for a walk: a leaf with a jagged edge, a track, something older than you, something that wasn't here yesterday.","9-12":"Your child writes a list of 10 finds for you and leads the route. On the way they photograph the strangest thing they notice."},"why":"Searching by a feature trains attention and the ability to notice details all around.","tip":"Don’t point out the find yourself. Narrow it down: “Look lower. Warmer!”","need":{"3-5":"a walk, a bag or a small bucket","6-8":"a list of 8 finds on a sheet of paper, a pencil","9-12":"a sheet of paper, a pen, a phone with a camera"},"steps":{"3-5":["Name four things to find: something round, something soft, something yellow, something noisy.","Look for one at a time. Your child shows you each find.","Ask about each: how does it feel?","At home, recall all four finds."],"6-8":["Write the list: a leaf with jagged edges, a track, something older than you, something that wasn’t here yesterday, and four of your own.","On the walk, your child searches and crosses them off.","For the debatable ones, let them prove it fits.","Which find was the hardest?"],"9-12":["Your child writes a list of 10 finds for you.","Leads the way while you search.","Along the way, they photograph the strangest thing they notice.","At home, look through the photos and pick the find of the day."]}},{"id":"explorer-2","scale":"explorer","art":"🗺️❌🧸","title":"Map of the room","task":{"3-5":"Hide a toy and give clues: \"next to the bed\", \"under the table\". Then your child hides it.","6-8":"Your child draws a map of the room from above and marks hidden treasure with an X. You search using the map.","9-12":"Your child draws a map of the way from home to school or a store from memory. Then you walk the route and correct the map."},"why":"A map teaches your child to picture a space from above and put it on paper.","tip":"Follow the map honestly. If it’s off, let your child see for themselves where it went wrong.","need":{"3-5":"a favorite toy","6-8":"a sheet of paper, a pencil, a small “treasure”","9-12":"a sheet of paper, a pencil"},"steps":{"3-5":["Hide the toy in the room while your child isn’t looking.","Give clues in words: “next to the bed”, “under the table”.","Found it? Now they hide it and give you the clues.","Play three rounds."],"6-8":["Your child draws the room from above: the bed, the table, the door.","Hides the treasure and marks an X on the map.","You search using only the map.","Swap: you draw the map."],"9-12":["From memory, your child draws the route from home to school or the store.","Marks the turns and three landmarks.","Walk the route together with the map in hand.","Correct whatever didn’t match on the map."]}},{"id":"explorer-3","scale":"explorer","art":"🤫👂🐦","title":"Five quiet minutes","task":{"3-5":"Sit by a window for 2 minutes. What can you hear? Count the sounds on your fingers.","6-8":"5 silent minutes outside. Then each of you names three things you noticed and the other didn't.","9-12":"10 minutes watching one spot (a bird feeder, an intersection, an anthill). Your child notes what happens and finds one pattern."},"why":"Quiet watching teaches your child to notice what usually slips by. It is an explorer’s main tool.","tip":"Stay silent along with your child. Your example works better than “sit still”.","need":{"3-5":"a window or a bench","6-8":"a yard or a park, a 5-minute timer","9-12":"a notebook, a pen, a spot to watch: a bird feeder, an intersection, an anthill"},"steps":{"3-5":["Sit side by side for 2 minutes.","Close your eyes and listen.","Count each new sound on your fingers.","Which sound was the quietest?"],"6-8":["Agree: 5 minutes of silence and looking.","Each of you remembers what you noticed.","Then take turns naming three things each.","The winner noticed something the other one missed."],"9-12":["Your child picks one spot and watches for 10 minutes.","Writes down what happens and when.","Looks for one pattern: what repeats?","Tells you the conclusion and how to check it tomorrow."]}},{"id":"explorer-4","scale":"explorer","art":"🧦🔴🗂️","title":"My collection","task":{"3-5":"Sort large lids, socks or toy blocks into piles: by color, then by size.","6-8":"Collect 10 leaves or stones. Your child decides how to split them into groups and explains the rule.","9-12":"Start a one-week collection: one find a day with a label saying where and when it was found. At the end of the week make a display."},"why":"Sorting teaches your child to find a feature and explain the rule. All classification starts here.","tip":"Don’t suggest the rule. Ask: “Why do these go together?”","need":{"3-5":"large lids, socks or blocks","6-8":"10 leaves or stones from a walk","9-12":"a box or a shelf, slips of paper for labels"},"steps":{"3-5":["Tip the items out on the floor.","Sort them by color together.","Mix them up and sort by size: big and small.","Let your child think of a third way."],"6-8":["Spread the finds out on the table.","Your child decides how to divide them into groups.","Explains the rule.","Ask them to sort again by a different rule."],"9-12":["Your child chooses a theme for a week-long collection.","One find each day, with a label: where and when it was found.","At the end of the week, turns them into an exhibit.","Gives the family a two-minute tour."]}},{"id":"explorer-5","scale":"explorer","art":"❓📗🔭","title":"Question of the day","task":{"3-5":"Your child asks one \"why\" question. Look for the answer together: in a book, outdoors or by testing.","6-8":"Your child picks an animal and finds three facts about it that you didn't know. Check whether you really didn't.","9-12":"Your child picks a question with no quick answer, finds two different sources and tells you where they disagree."},"why":"Your child learns to find an answer on their own and check it. That skill lasts through all of school.","tip":"Say honestly, “I don’t know, let’s find out.” It is the best example for an explorer.","need":{"3-5":"a children’s encyclopedia or a window","6-8":"a book about animals, or searching together with an adult","9-12":"two sources: a book and a website, or two websites"},"steps":{"3-5":["Your child asks one “why” question.","Say: let’s find out together.","Look for the answer in a book, outside or with a simple experiment.","Ask them to tell the answer to another adult."],"6-8":["Your child picks an animal.","Finds three facts about it that you didn’t know.","Tells you.","Say honestly which ones you really didn’t know."],"9-12":["Your child picks a question with no quick answer.","Finds two different sources.","Compares: where do they agree and where do they differ?","Tells you which one they trust more, and why."]}},{"id":"leader-1","scale":"leader","art":"⏱️👑🎲","title":"Captain for 15 minutes","task":{"3-5":"For 15 minutes your child is in charge: picks the game and says who does what. You follow.","6-8":"Your child plans a one-hour family walk: where to go, what to take, who is responsible for what.","9-12":"Your child organizes a family evening: a program, a role for everyone, a budget you set. Afterwards talk about how it went."},"why":"Your child tries being responsible for others: deciding, assigning, agreeing.","tip":"Follow orders for real. If a decision doesn’t work out, let them see the result themselves.","need":{"3-5":"a 15-minute timer","6-8":"a sheet of paper, a pencil","9-12":"a sheet of paper, a budget that you set"},"steps":{"3-5":["Announce: for 15 minutes, you’re in charge.","Your child chooses the game.","Says who does what. You follow.","When the timer rings, thank your “captain”."],"6-8":["The task: plan a one-hour family walk.","Your child decides where you go and what you bring.","Assigns who is responsible for what.","Go by their plan. What worked?"],"9-12":["Your child organizes a family evening.","Draws up a program and a role for everyone.","Stays within the budget.","Afterwards, talk it over: what worked, and what would they do differently?"]}},{"id":"leader-2","scale":"leader","art":"⚽📋🎲","title":"A new game","task":{"3-5":"Make up a ball game with one rule. Play it. Your child adds a second rule.","6-8":"Your child invents a game with three rules and explains it to the family. If someone doesn't get it, the rule needs simpler words.","9-12":"Your child designs a board game on a sheet of paper: the goal, the moves, how to win. Play it and fix one weak rule together."},"why":"Making a rule and explaining it to others is how a child learns to lead without shouting.","tip":"If a rule isn’t clear, don’t fill in the gaps. Say: “I didn’t get it. Can you make it simpler?”","need":{"3-5":"a ball","6-8":"any toys or a ball","9-12":"a sheet of paper, a pencil, a die, game pieces"},"steps":{"3-5":["Make up a ball game with one rule. For example: we only roll it sitting down.","Play for two minutes.","Your child adds a second rule.","Play by the new rules."],"6-8":["Your child invents a game with three rules.","Explains it to the family.","Someone didn’t get it? The rule needs to be put more simply.","Play one round."],"9-12":["Your child draws a board game: the goal, the moves, how to win.","Play a game.","Find one weak rule together.","Fix it and play again."]}},{"id":"leader-3","scale":"leader","art":"🍎🍌💬","title":"Convince me","task":{"3-5":"Your child chooses between two things (apple or banana) and says why. One reason is enough.","6-8":"Your child wants to change something at home (bedtime, the menu). Ask for three reasons. Good arguments win.","9-12":"A debate with rules: your child argues for a view for 2 minutes, then for the opposite for 2 minutes. Which side turned out stronger?"},"why":"Your child learns to get their way with reasons, not with persistence.","tip":"Decide in advance what you’re willing to agree to. The final word stays with you.","need":{"3-5":"two things to choose from: an apple and a banana, two books","6-8":"nothing needed","9-12":"a timer"},"steps":{"3-5":["Offer a choice of two.","Your child chooses and says why.","One reason is enough.","Repeat their reason aloud: “You chose the banana because it’s sweet.”"],"6-8":["Your child names one thing they’d like to change at home.","Gives three reasons.","You respond to each one on its merits.","Good reasons count. The decision is yours, and you explain it."],"9-12":["Pick a topic to debate.","For two minutes your child defends their own view.","For two minutes they defend the opposite one.","Which side turned out stronger, and why?"]}},{"id":"leader-4","scale":"leader","art":"🤝🧺⭐","title":"First mate","task":{"3-5":"Today you are in charge and your child is the helper: you ask, they do three jobs. Thank them for each.","6-8":"In today's game your child doesn't lead but helps a younger child or you. Then ask: what was hard?","9-12":"Your child helps someone else finish their idea without replacing it with their own. Then talk about where they wanted to take over."},"why":"A leader also needs to know how to be second: to listen, to help and not to take over.","tip":"Thank them for something specific: “You brought everything at once, so we made it in time.”","need":{"3-5":"three simple chores","6-8":"any game","9-12":"someone else’s idea: a sibling’s project or yours"},"steps":{"3-5":["Announce: today I’m in charge and you’re my helper.","Ask for the first chore.","Say thank you and name the second, then the third.","Tell them how their help made a difference."],"6-8":["Today your child isn’t “it” and doesn’t lead the game.","They help a younger child or you.","Play for 10 minutes.","Ask: what was hard? What did you like?"],"9-12":["Your child chooses who to help.","The task: carry someone else’s idea through without turning it into their own.","Works for 10 minutes.","Talk about it: at what point did they want to do it their way?"]}},{"id":"leader-5","scale":"leader","art":"🪙🛒🍪","title":"A small venture","task":{"3-5":"Play store: your child is the seller, you are the customer. They name the price and count the \"coins\" cut from paper.","6-8":"Your child decides what to make for neighbors or family (cards, cookies) and hands out tasks to the family.","9-12":"Your child plans a small weekend venture: what we do, for whom, what it costs. They add up the costs and the result."},"why":"A small venture with a price and a result teaches counting, planning and thinking of others.","tip":"Let your child do the math. Find any mistake together.","need":{"3-5":"toys as “goods”, paper “coins”","6-8":"paper and pencils, or ingredients for cookies","9-12":"a sheet of paper, a calculator"},"steps":{"3-5":["Cut out 10 paper coins in advance.","Your child sets out the goods: they are the shopkeeper.","You shop. They name the price and count the coins.","Swap roles."],"6-8":["Your child decides what to make for the neighbors or relatives.","Hands out tasks to the family.","You make it together following their plan.","They deliver the result themselves."],"9-12":["Your child comes up with a small project for the weekend.","Writes down: what we’re doing, for whom, what it costs.","Adds up the costs.","After the weekend, sums up how it went."]}},{"id":"helper-1","scale":"helper","art":"😀😢😮","title":"How do they feel","task":{"3-5":"Show with your face: joy, sadness, anger, surprise. Your child guesses and copies.","6-8":"Open a book to a picture. How does each character feel? What shows it?","9-12":"Watch a minute of a movie with no sound. Your child explains how the characters feel and what was probably said."},"why":"Your child learns to read feelings from a face and a posture. That is the basis of empathy.","tip":"Name your own feelings too: “I’m tired right now, you can see it in my shoulders.”","need":{"3-5":"a mirror (optional)","6-8":"a picture book","9-12":"a minute of a movie with the sound off"},"steps":{"3-5":["Show joy with your face. Your child guesses.","Then sadness, anger, surprise.","Your child copies each expression.","Now they show and you guess."],"6-8":["Open the book to a picture with several characters.","What is each one feeling?","How can you tell: the face, the hands, the posture?","What would the character say if they could?"],"9-12":["Play one minute of a movie with no sound.","Your child explains what the characters are feeling.","Says what was most likely said.","Play it with sound and compare."]}},{"id":"helper-2","scale":"helper","art":"🎁🤫💛","title":"Secret kind deed","task":{"3-5":"Make a surprise for someone at home together: a drawing under a pillow or a table set for them.","6-8":"Your child picks a person and does one kind thing for them so that they don't know who did it.","9-12":"Your child notices who in the family is having a hard time and decides how to help. You only supply what's needed."},"why":"A kind deed with no reward teaches caring for the other person’s sake, not for praise.","tip":"Keep the secret. Don’t tell who made the surprise.","need":{"3-5":"paper, crayons, or dishes for the table","6-8":"nothing needed","9-12":"whatever the help requires"},"steps":{"3-5":["Choose who at home will get a surprise.","Decide what: a drawing under the pillow or a set table.","Do it together, quietly.","Watch from a distance as the person is delighted."],"6-8":["Your child chooses a person.","Thinks of one kind thing to do for them.","Does it so the person doesn’t find out who did it.","In the evening, tells you how it felt."],"9-12":["Your child notices who in the family is having a hard time right now.","Works out how to help on their own.","You only provide what’s needed.","Later, ask: how did they know the person needed help?"]}},{"id":"helper-3","scale":"helper","art":"📕📗☝️","title":"What do I want","task":{"3-5":"Offer a choice of two: which book to read, which cup to use. Your child chooses for themselves, out loud.","6-8":"Today your child says \"I want…\" three times and politely says \"no\" once. Practice it in a game.","9-12":"Go over a time when your child agreed although they didn't want to. How could they have said no kindly? Practice the phrase."},"why":"A caring child also needs to hear their own wishes, not just other people’s.","tip":"Take their “no” calmly. That is how they learn that saying no doesn’t break a relationship.","need":{"3-5":"two books or two cups","6-8":"nothing needed","9-12":"nothing needed"},"steps":{"3-5":["Offer a choice between two things.","Your child chooses and says out loud: “I want this one.”","Repeat the choice three times during the day, in different situations.","Don’t ask twice and don’t offer a third option."],"6-8":["Play a game: you offer, they answer.","The task: say “I want…” three times.","And politely say “no” once.","Tell them you liked how they said no."],"9-12":["Recall a time when your child agreed to something they didn’t want.","Talk about it: what made it hard to say no?","Come up with a sentence that won’t hurt anyone’s feelings.","Practice it aloud twice."]}},{"id":"helper-4","scale":"helper","art":"💌🖍️🙏","title":"A thank-you note","task":{"3-5":"Your child draws a card for someone who helped them. You write their words on it.","6-8":"Your child writes a three-sentence thank-you to a teacher, coach or neighbor: for what exactly and what it changed.","9-12":"Your child writes a letter to someone they haven't thanked in a long time and decides how to deliver it."},"why":"Saying thank you in words teaches your child to notice what others do for them.","tip":"Help them recall something specific: “Thank you for what, exactly?”","need":{"3-5":"paper, crayons","6-8":"a sheet of paper, a pen","9-12":"paper, a pen, an envelope"},"steps":{"3-5":["Ask: who helped you lately?","Your child draws a card for that person.","You write down their words without changing anything.","Hand it over together."],"6-8":["Your child chooses: a teacher, a coach or a neighbor.","Writes three sentences: thank you for what, and what it changed.","You don’t edit the text; fix spelling only if they ask.","They hand over the note themselves."],"9-12":["Your child thinks of someone they haven’t thanked in a long time.","Writes them a letter.","Decides how to deliver it: in person, by mail, by message.","Delivers it this week."]}},{"id":"helper-5","scale":"helper","art":"🧑‍🏫🪥🧥","title":"Teacher for 10 minutes","task":{"3-5":"Your child teaches a toy or you something they can do: brush teeth, put on a jacket.","6-8":"Your child teaches you or a younger child one thing they do well. You try hard and sometimes get it wrong.","9-12":"Your child prepares a ten-minute lesson for the family on a topic they know well: an explanation, an example, a check question."},"why":"By explaining to someone else, your child understands better and feels capable.","tip":"Be an eager student and make a mistake now and then. Let them correct you.","need":{"3-5":"a toy, a toothbrush or a jacket","6-8":"something your child is good at","9-12":"a sheet of paper for a plan"},"steps":{"3-5":["Ask: what can you do all by yourself?","Your child teaches a toy or you: brushing teeth, putting on a jacket.","Make a mistake. Let them show you the right way.","Thank your teacher."],"6-8":["Your child picks one skill.","Teaches you or a younger child, step by step.","You try hard and make one mistake.","At the end, show what you’ve learned."],"9-12":["Your child picks a topic they know well.","Prepares a 10-minute lesson: an explanation, an example, a quiz question.","Teaches it to the family.","Everyone names one thing they learned."]}},{"id":"mover-1","scale":"mover","art":"🪑🧗🏁","title":"Obstacle course","task":{"3-5":"Cushions, a chair, a rope on the floor: step over, crawl under, walk the line. Three laps.","6-8":"Your child builds a 5-obstacle course at home and runs it against the clock. Is the second try faster?","9-12":"Your child builds a 6-stage course and sets penalty rules. Both of you run it timed, three tries, results written down."},"why":"An obstacle course builds coordination and the ability to plan a movement.","tip":"Clear sharp corners and slippery rugs out of the way. Praise care, not just speed.","need":{"3-5":"pillows, a chair, a rope or a belt","6-8":"pillows, chairs, a rope, a stopwatch","9-12":"household items, a stopwatch, paper for scores"},"steps":{"3-5":["Lay the rope on the floor as a line, with the pillows and the chair nearby.","Show the route: step over, crawl under the chair, walk along the line.","Your child does three laps.","Do the last lap together."],"6-8":["Your child builds a course with 5 obstacles.","Runs it against the clock.","Second try: can it be faster?","Ask which obstacle is the hardest."],"9-12":["Your child builds a 6-stage course.","Sets the penalty rules for mistakes.","You both run it, three tries each.","Write down the results. Who improved more?"]}},{"id":"mover-2","scale":"mover","art":"🎶🕺🧊","title":"Freeze","task":{"3-5":"Music on, everyone dances. Music off, everyone freezes. Who can stay still to the count of 5?","6-8":"Dance and freeze on one leg. Each round, hold it 2 seconds longer.","9-12":"Freeze with a task: on the signal take a pose (plank, airplane, squat) and hold for 20 seconds. Your child picks the poses for you."},"why":"The freeze game trains stopping on a signal. That is the basis of self-control.","tip":"Play along. Your child needs to see that freezing is hard for you too.","need":{"3-5":"music","6-8":"music","9-12":"music, a timer"},"steps":{"3-5":["Turn on music and dance together.","Stop the music: everyone freezes.","Count out loud to 5.","Play five rounds."],"6-8":["Dance to the music.","When it stops, freeze on one leg.","Hold it 2 seconds longer each round.","What count did you reach?"],"9-12":["When the music stops, strike a pose: plank, airplane balance or squat.","Hold for 20 seconds.","Your child chooses the poses for you.","Five rounds, then swap."]}},{"id":"mover-3","scale":"mover","art":"🤹⚽📈","title":"A new trick","task":{"3-5":"Toss a soft ball up and catch it with both hands. Then clap while the ball is in the air.","6-8":"Pick a trick: 10 jump-rope jumps in a row or keeping a balloon up for 20 hits. Five minutes of practice, then the test. If the balloon pops, an adult picks up the pieces.","9-12":"Your child picks a skill for the week (juggling two balls, a wall handstand, foot juggling with a ball). Today: the first measure and a plan."},"why":"Your child sees that a skill grows with practice. That changes how they feel about hard things.","tip":"Count tries, not mistakes: “That was number twelve, and it was steadier.”","need":{"3-5":"a soft ball","6-8":"a jump rope or a balloon","9-12":"two balls or a wall, paper for scores"},"steps":{"3-5":["Your child tosses the ball up and catches it with both hands.","Five times in a row.","Make it harder: clap while the ball is in the air.","How many claps did they manage?"],"6-8":["Pick a trick: 10 jumps in a row or keeping the balloon up for 20 taps.","Five minutes of practice.","Then the test: count out loud.","An adult picks up a popped balloon."],"9-12":["Your child picks a skill for the week: juggling, a handstand against the wall, keepy-uppies.","Today is the first measure: how many can they do now?","They make a plan: 5 minutes a day.","Put the score sheet up where everyone can see it."]}},{"id":"mover-4","scale":"mover","art":"🐻🔤🤸","title":"Body letters","task":{"3-5":"Show animals with your body: how a bear walks, a hare hops, a snake crawls. Your child guesses and copies.","6-8":"Your child shapes the letters of their name with their body and you guess. Then shape a word together.","9-12":"Times tables on the move: the answer is not said but jumped or bounced with a ball. 10 problems against the clock."},"why":"Movement helps memory: letters and numbers that the body has acted out stick longer.","tip":"Laugh together. The funnier the pose, the better it sticks.","need":{"3-5":"some free space","6-8":"some free space","9-12":"a ball, a timer"},"steps":{"3-5":["Show how a bear walks.","Your child guesses and copies.","Then a rabbit and a snake.","Now they choose the animal."],"6-8":["Your child makes the first letter of their name with their body.","You guess.","They show the other letters.","Make a short word together."],"9-12":["You call out a multiplication problem.","The answer has to be jumped or bounced with the ball.","Ten problems for speed.","Swap: your child sets the problems."]}},{"id":"mover-5","scale":"mover","art":"🏃🧸😌","title":"A quiet minute after running","task":{"3-5":"Run and jump for two minutes. Then lie on your back with a toy on your belly: how does it rock?","6-8":"5 minutes of active play, then 5 minutes of a quiet activity (a puzzle, a drawing). Notice together: is sitting easier after moving?","9-12":"Your child runs their own test: reads for 10 minutes after a warm-up and 10 minutes without one. When did more stick?"},"why":"Your child notices for themselves that it’s easier to focus after moving. You can use this every day.","tip":"Put the finding to use: give five minutes of movement before homework or reading.","need":{"3-5":"a soft toy, a mat","6-8":"a puzzle, or paper and pencils","9-12":"a book, a timer"},"steps":{"3-5":["Run and jump together for two minutes.","Lie down on your backs.","Put the toy on your child’s tummy.","Watch together how it rocks with each breath."],"6-8":["Five minutes of active play.","Five minutes of a quiet activity: a puzzle or drawing.","Ask: is it easy to sit still right now?","Compare with how it is without a warm-up."],"9-12":["Your child reads for 10 minutes after a warm-up.","Retells what they remember.","Another day, reads for 10 minutes without a warm-up.","Compares: when did more stick?"]}},{"id":"builder-6","scale":"builder","art":"🥄📄🎯","title":"Spoon catapult","why":"Your child meets the lever: a small shift of the pivot changes force and distance.","tip":"Launch only soft paper balls, and only away from people.","need":{"3-5":"a tablespoon, paper balls, a bowl","6-8":"a ruler, a pencil, paper balls, a sheet of paper","9-12":"a ruler, an eraser or a pencil, paper balls, a tape measure, a sheet of paper"},"steps":{"3-5":["Crumple five paper balls together.","Put a ball in the spoon and the spoon on the edge of the table. Your child slaps the handle.","Set the bowl one step from the table. Can they land a ball in it?","Count the hits out of five."],"6-8":["Lay the ruler across the pencil like a seesaw. Put a ball on one end.","Your child presses the other end and watches where the ball goes.","Move the pencil closer to the ball, then farther. Three launches for each position.","Where does the ball fly farthest? Let them explain in their own words."],"9-12":["The challenge: find the pivot position for the longest launch.","Your child picks three positions and does three launches each.","Records the distances in a table.","Sums up the finding in one sentence and tests it with a fourth position."]}},{"id":"builder-7","scale":"builder","art":"🪑🛋️⛺","title":"Blanket fort","why":"A fort teaches how to build a frame: what holds, what covers and where the weak spot is.","tip":"Don’t fix a sagging roof. Ask: “What’s holding it up? What’s missing?”","need":{"3-5":"two chairs, a blanket, pillows","6-8":"chairs, blankets, clothespins, pillows","9-12":"blankets, clothespins, chairs, string, a sheet of paper"},"steps":{"3-5":["Stand the chairs back to back, one step apart.","Cover them with the blanket together.","Your child chooses where the entrance is and sets up a spot inside with pillows.","Climb in together and read one book."],"6-8":["The challenge: a fort that fits two people.","Your child chooses the supports and clips the blanket on with clothespins.","The test: both of you climb in. Does the roof hold?","Find the weak spot and reinforce it."],"9-12":["Start with a plan: two “rooms” and an entrance.","Your child builds to the plan from what you have at home.","The test: five minutes inside together without fixing anything.","What would they change in the plan next time?"]}},{"id":"builder-8","scale":"builder","art":"✈️📄📏","title":"Record-breaking paper plane","why":"Your child changes one detail and measures the result. That is how a test engineer works.","tip":"Launch down a hallway, never toward people. Change only one detail at a time.","need":{"3-5":"two sheets of paper","6-8":"three sheets of paper, a sheet for scores","9-12":"paper, a paper clip, a tape measure, a sheet of paper"},"steps":{"3-5":["Fold a paper plane slowly while your child watches.","Your child launches it three times.","Measure the longest flight in steps.","Let them color the wings and launch it again."],"6-8":["Fold two different models together: a narrow one and a wide one.","Three launches each. Measure distance in steps.","Which one flies farther? Which one flies straighter?","Your child names the models and writes down the record."],"9-12":["Your child folds one model and does three baseline launches.","Changes one detail: a paper clip on the nose or bent wing edges.","Three more launches, results in a table.","The finding: what helped, what hurt, and why."]}},{"id":"inventor-6","scale":"inventor","art":"🔦🧸👤","title":"Shadow experiments","why":"Your child finds the link between distance to the light and the size of a shadow. It is a first step toward understanding cause and effect.","tip":"Don’t explain in advance. Ask: “How can we make the shadow bigger?” and let them try.","need":{"3-5":"a flashlight, a toy, a wall","6-8":"a flashlight, a toy, a sheet of paper, a pencil","9-12":"a flashlight, an object, a ruler, a sheet of paper"},"steps":{"3-5":["Turn off the ceiling light and shine the flashlight on a toy near the wall.","Find the shadow together.","Move the flashlight closer, then farther. What happened to the shadow?","Your child makes a giant shadow and a tiny shadow."],"6-8":["Tape the sheet to the wall. Your child sets up the toy and shines the light.","Trace the shadow with the pencil.","The challenge: make the shadow twice as big. What has to move?","Trace the new shadow and compare."],"9-12":["Your child places the flashlight at three distances from the object.","Each time measures the height of the shadow and writes it down.","Looks for the rule: what happens to the shadow when the light is closer?","Tests the rule at a fourth distance."]}},{"id":"inventor-7","scale":"inventor","art":"🧊🧂⏱️","title":"Save the ice cube","why":"Your child compares conditions and sees that a result has a cause you can find.","tip":"Ask for a prediction before the test. It didn’t come true? That’s the most interesting part.","need":{"3-5":"two ice cubes, two plates","6-8":"three ice cubes, three saucers, salt, warm water","9-12":"ice cubes, foil, cloth, paper, a small box, a clock"},"steps":{"3-5":["Put one ice cube on each plate.","Put one plate somewhere warm and the other somewhere cool.","Ask: which one will melt first?","Check every five minutes. The ice doesn’t go in the mouth."],"6-8":["Your child predicts which cube will melt first.","Sprinkles salt on the first, pours warm water on the second, leaves the third alone.","Watches for ten minutes.","Which prediction came true? What was surprising?"],"9-12":["The challenge: keep an ice cube frozen as long as possible.","Your child designs packaging from things around the house.","Puts an unwrapped ice cube next to it for comparison.","Times both and explains what worked."]}},{"id":"inventor-8","scale":"inventor","art":"☕💡🛠️","title":"Make it better","why":"Your child learns to notice what’s awkward and propose a fix. That is how inventions are born.","tip":"Ask: “What bugs you about this thing?” Every improvement starts there.","need":{"3-5":"a cup or a spoon, a sheet of paper, crayons","6-8":"a sheet of paper, pencils","9-12":"cardboard, tape, scissors"},"steps":{"3-5":["Pick up a cup. Ask: what could we add to make it better?","Accept any idea: wings, wheels, a second handle.","Draw the new cup together.","Give it a name."],"6-8":["Your child picks something they use every day: a backpack, a pencil case, a bed.","Says what’s awkward about it.","Comes up with three improvements and draws them.","Chooses one that can be done today."],"9-12":["Your child finds one annoyance at home: tangled cords, shoes all over the place.","Thinks up a solution and builds a trial version from cardboard.","The family uses it for three days.","They collect feedback and improve it."]}},{"id":"storyteller-6","scale":"storyteller","art":"📷👨‍👩‍👧💭","title":"Story from a photo","why":"Your child fills in what isn’t in the frame: the cause and what comes next. That is the basis of a plot.","tip":"Ask “what makes you think so?” so your child leans on details in the picture.","need":{"3-5":"a family photo","6-8":"a photo from a magazine or a book","9-12":"three photos, a sheet of paper"},"steps":{"3-5":["Open a photo that shows your child or people close to them.","Ask: who is here? What are they doing?","And what happened next? Your child makes it up.","Tell them how it really went."],"6-8":["Pick a photo of people you don’t know.","Your child tells what happened a minute before the photo.","And what will happen a minute after.","Which detail in the photo gave them the idea?"],"9-12":["Your child picks three completely unrelated photos.","Lines them up: beginning, middle, end.","Writes two sentences for each so they make one story.","Changes the order of the photos. What’s the new story?"]}},{"id":"storyteller-7","scale":"storyteller","art":"👽🪥💬","title":"Explain it to an alien","why":"Explaining something simple to someone who knows nothing is how you learn to speak clearly.","tip":"Play it straight. Keep asking: “And what is water?”","need":{"3-5":"a soft toy","6-8":"a toothbrush or another everyday object","9-12":"a timer"},"steps":{"3-5":["The toy has arrived from another planet and knows nothing.","Your child explains to it what rain is.","The toy asks one question in your voice.","Then they explain how to eat soup."],"6-8":["You’re the alien. Your child explains what a toothbrush is for.","The rule: the word “brush” is off limits.","Ask two naive questions.","Swap: you explain and they ask."],"9-12":["Pick a topic: the internet, money or school.","Your child explains it in one minute in simple words.","Beforehand, you ban the three most obvious words.","Say back what you understood. Does it match what they meant?"]}},{"id":"storyteller-8","scale":"storyteller","art":"🐱🎩🎶","title":"Rhymes and lines","why":"Rhyme tunes the ear to language and teaches how to pick the exact word.","tip":"Silly and nonsense rhymes count too. What matters is that it’s fun.","need":{"3-5":"nothing needed","6-8":"a sheet of paper, a pencil","9-12":"a sheet of paper, a pen"},"steps":{"3-5":["Say a simple word, like “cat”.","Look together for words that sound alike.","Make a funny line out of two of them.","Say it together three times."],"6-8":["The topic: a favorite toy or a pet.","Your child finds two pairs of rhyming words.","Builds four lines out of them.","Reads the poem to the family with feeling."],"9-12":["Your child picks a favorite thing or dish.","Writes a four-line rhyming ad for it.","Comes up with a short slogan.","Reads it like an announcer. You say whether you’d buy it, and why."]}},{"id":"artist-6","scale":"artist","art":"🙂✏️🖼️","title":"Portrait","why":"To draw a face, you have to look closely. That is how the hand learns to trust the eye.","tip":"Don’t judge the likeness. Ask: “What did you notice about me?”","need":{"3-5":"a sheet of paper, crayons","6-8":"a sheet of paper, a marker","9-12":"two sheets, a pencil"},"steps":{"3-5":["Sit facing your child.","They draw a big circle: that’s your face.","Name them one by one: eyes, nose, mouth, hair. They add each.","Now you draw them, and they tell you what to add."],"6-8":["The rule: draw a portrait without lifting the marker from the paper.","Your child draws you in one line.","You draw them the same way.","Find the best detail in each portrait."],"9-12":["First portrait: your child looks only at you, never at the paper.","Two minutes, moving the line slowly.","The second portrait is a regular one, also two minutes.","Compare: which one has more character?"]}},{"id":"artist-7","scale":"artist","art":"🤸✨🗿","title":"Foil figure","why":"A 3D figure teaches your child to see a shape from every side and to show movement.","tip":"Ask them to strike the pose with their own body first. Then it’s easier to shape.","need":{"3-5":"modeling clay or salt dough","6-8":"foil","9-12":"foil or modeling clay"},"steps":{"3-5":["Roll three balls and three snakes together.","Ask: what animal can we build from these?","Your child joins the parts.","The animal tells its name in your voice."],"6-8":["Tear off a piece of foil the size of a sheet of paper.","Your child scrunches it into a little person: head, arms, legs.","The challenge: the person is running, sitting or dancing.","You guess what they’re doing."],"9-12":["The challenge: a figure with no face that shows a feeling.","Your child picks the feeling and doesn’t tell you.","Shapes it for five minutes.","You guess. What in the pose gave it away?"]}},{"id":"artist-8","scale":"artist","art":"🪟🌇✏️","title":"View from the window","why":"Your child learns to choose what goes into the frame and to notice how light changes a familiar place.","tip":"Ask: “What’s the main thing here?” That is composition.","need":{"3-5":"a window, a sheet of paper, crayons","6-8":"a cardboard frame or your fingers, paper, pencils","9-12":"two sheets, a pencil"},"steps":{"3-5":["Look out the window together for one minute.","Your child names three things they see.","Draws them on the sheet.","Ask which of the three they like best."],"6-8":["Make a frame from cardboard or with your fingers.","Your child looks through it out the window and chooses a shot.","Draws only what’s inside the frame.","Gives the drawing a title."],"9-12":["Your child sketches the view from the window in the morning, five minutes.","In the evening does a second one from the same spot.","Puts them side by side.","What did the light change: colors, shadows, mood?"]}},{"id":"explorer-6","scale":"explorer","art":"🍃🖍️🌳","title":"Rubbings","why":"Your child explores surfaces with hands and eyes and learns to recognize a thing by the mark it leaves.","tip":"Guess out loud and get it wrong. Let your child correct you.","need":{"3-5":"paper, a wax crayon, a tree leaf, a big lid","6-8":"paper, a crayon or a soft pencil","9-12":"paper, a soft pencil, a field guide or an app"},"steps":{"3-5":["Put the leaf under the paper.","Your child rubs over it with the side of the crayon.","Watch the pattern appear together.","Repeat with the lid. How are the rubbings different?"],"6-8":["On a walk, your child makes five rubbings of different surfaces.","Bark, paving, a bench, a leaf, a wall.","At home you guess which is which.","They only give hints: “warmer” and “colder”."],"9-12":["Your child makes bark rubbings of three different trees.","Collects a leaf from each.","Identifies the trees with a book or an app.","Labels the rubbings and puts together a catalog page."]}},{"id":"explorer-7","scale":"explorer","art":"🌤️🌧️📝","title":"Weather office","why":"Watching the weather teaches your child to notice signs and make a forecast that can be checked.","tip":"The forecast was off? Ask which sign let them down.","need":{"3-5":"a window, a toy, clothes for it or a scrap of fabric","6-8":"a sheet of paper, a pencil","9-12":"a sheet of paper or a notebook, an outdoor thermometer or a phone"},"steps":{"3-5":["Look out the window: sun, clouds or rain?","Are the branches moving? Then it’s windy.","Your child decides how to dress the toy today.","On your walk, check whether they got it right."],"6-8":["In the evening, look at the sky together.","Your child writes a forecast for tomorrow: sun, clouds or rain.","Checks it in the morning.","Three days in a row. How many forecasts were right?"],"9-12":["For a week, at the same time each day, your child records temperature, clouds and wind.","Each evening writes their own forecast for tomorrow.","Compares it with the phone forecast and with what really happened.","At the end of the week, counts who was more accurate."]}},{"id":"explorer-8","scale":"explorer","art":"👀🧩❔","title":"What changed?","why":"The game trains visual memory and attention to detail.","tip":"Start easy. Make it harder only after two wins in a row.","need":{"3-5":"a tray, five large objects, a towel","6-8":"a room","9-12":"a painting or a photo with lots of detail, a sheet of paper"},"steps":{"3-5":["Lay five objects on the tray and name them together.","Cover with the towel and quietly take one away.","What’s missing?","Now your child takes one away and you guess."],"6-8":["Your child studies the room for a minute and steps out.","You change three things: move one, remove one, flip one over.","They look for the changes.","Swap roles."],"9-12":["Your child studies the picture for one minute.","Take it away and ask ten questions about details.","Count the right answers.","Now they prepare ten questions for you."]}},{"id":"leader-6","scale":"leader","art":"👨‍👩‍👧🗳️✅","title":"Family council","why":"Your child learns to hear everyone out and bring a discussion to a decision.","tip":"Speak only when it’s your turn. They’ll see that the council rules apply to everyone.","need":{"3-5":"two options for dinner or a walk","6-8":"a 5-minute timer","9-12":"a sheet of paper, a timer"},"steps":{"3-5":["Give your child two options.","They ask everyone in the family which one they choose.","Count the votes on fingers.","Announce the result."],"6-8":["The council question: what shall we do this weekend?","Your child gives everyone a turn to speak.","Repeats all the suggestions aloud.","Holds a vote and announces the decision."],"9-12":["Your child prepares three topics to discuss.","Runs the council: three minutes per topic.","Writes down the decisions and who is responsible for what.","A week later, checks what got done."]}},{"id":"leader-7","scale":"leader","art":"🧸📦🚀","title":"Mission commander","why":"Your child splits a big job into parts and hands out tasks. That is the basis of organizing.","tip":"Carry out each order exactly as given. An unclear order will show right away.","need":{"3-5":"scattered toys, boxes","6-8":"a room, a 10-minute timer","9-12":"a sheet of paper, ingredients for a simple breakfast"},"steps":{"3-5":["The mission: rescue the toys and bring them home.","Your child is the commander: they say which toy goes where.","You carry it out and report: “Teddy is home!”","Celebrate the end of the mission."],"6-8":["The mission: a tidy room in 10 minutes.","Your child divides the room into zones and assigns them.","Keeps an eye on the time and helps whoever falls behind.","At the end, thanks the team."],"9-12":["The mission: breakfast for the family in 20 minutes.","Your child writes a task list and the order.","Hands out the tasks. An adult handles the stove and the knife.","After breakfast, a debrief: what would they assign differently?"]}},{"id":"leader-8","scale":"leader","art":"⚖️🎲🤝","title":"Fair referee","why":"Your child learns to hear both sides and find a solution everyone can accept.","tip":"Accept the ruling, even if it doesn’t go your way.","need":{"3-5":"a simple turn-taking game: a ball or blocks","6-8":"a board game","9-12":"nothing needed"},"steps":{"3-5":["Your child keeps track of turns.","They say: “Now it’s your turn.”","Skip the line once. They should notice.","Thank them for a fair game."],"6-8":["Today your child is the referee.","Before the game, they announce the rules.","Stage a small dispute. They decide who is right.","Ask why they decided that way."],"9-12":["Take a real, small disagreement in the family.","Your child listens to both sides without interrupting.","Restates each side so that the person agrees with the summary.","Proposes a solution that works for both."]}},{"id":"helper-6","scale":"helper","art":"🪴💧🐹","title":"Caring for a living thing","why":"Regular care for a plant or a pet teaches responsibility for someone who depends on you.","tip":"Don’t remind them right away. Ask: “How’s your plant doing?”","need":{"3-5":"a houseplant, a small watering can, a damp cloth","6-8":"a plant or a pet, a paper calendar","9-12":"a plant or a pet, a book or a website, a sheet of paper"},"steps":{"3-5":["Choose a plant together: now it’s “theirs”.","Your child waters it a little.","Wipes one leaf with the cloth.","Ask: what does the plant like?"],"6-8":["Your child chooses who they’ll care for this week.","Together you find out what it needs and how often.","They mark what’s done on the calendar each day.","At the end of the week: what changed?"],"9-12":["Your child finds out what their charge needs: light, water, food.","Writes a care note for the family.","Is in charge of the care for a week.","Afterwards tells you what was hardest."]}},{"id":"helper-7","scale":"helper","art":"👂💬❤️","title":"I’m listening","why":"Listening without interrupting and saying back what you heard is the foundation of friendship.","tip":"Keep it short and real. A child can tell when a story is made up.","need":{"3-5":"nothing needed","6-8":"a 2-minute timer","9-12":"nothing needed"},"steps":{"3-5":["Tell them about your day in three sentences.","Your child says it back: “Today you…”","Ask: do you think I felt happy or sad?","Swap: they tell you."],"6-8":["You talk about your day for two minutes.","Your child listens without interrupting.","Asks one question.","Sums up the main point. Tell them whether they got it right."],"9-12":["Your child asks someone in the family how their day went.","Asks three follow-up questions.","Names the feeling: “Sounds like you were frustrated.”","Asks whether they got it right."]}},{"id":"helper-8","scale":"helper","art":"💛📝😊","title":"Kind words","why":"Your child learns to notice the good in others and say it in a specific way.","tip":"Set the example: tell your child exactly what they did well today.","need":{"3-5":"a family dinner","6-8":"slips of paper, a pencil","9-12":"a sheet of paper or notes on a phone"},"steps":{"3-5":["At dinner, your child says one kind thing to each person.","Offer a starter: “I like how you…”","Everyone answers “thank you”.","At the end, they get a kind word too."],"6-8":["Your child writes a note to everyone in the family.","Each one names something specific: “Thank you for fixing my bike.”","Hides the notes where they’ll be found.","In the evening, talk about who found what."],"9-12":["During the day, your child notices three good things other people do.","Writes down who did what.","In the evening, tells or writes to each person about it.","Talk it over: how did people react?"]}},{"id":"mover-6","scale":"mover","art":"🧘📚〰️","title":"Keep your balance","why":"Balance is tied to attention and posture, and it trains well through play.","tip":"Stand on one leg next to them. Wobbling is more fun together.","need":{"3-5":"a rope or a strip of tape on the floor, a soft toy","6-8":"a stopwatch","9-12":"a book, a stopwatch, a sheet of paper"},"steps":{"3-5":["Make a line on the floor.","Your child walks along it with arms out wide.","Now with a toy on their head.","Walk after them and drop the toy. Let them laugh."],"6-8":["Your child stands on one leg. Time it.","Then the other. Which is steadier?","Now with eyes closed, with you right there.","Write down the three results."],"9-12":["Your child walks across the room with a book on their head.","Harder: squat and stand up without dropping it.","Designs a route with a turn.","Three timed tries. Writes down the record."]}},{"id":"mover-7","scale":"mover","art":"🧦🧺🎯","title":"On target","why":"Throwing at a target builds hand-eye judgment and a feel for force.","tip":"Throw only soft things: rolled socks or paper balls.","need":{"3-5":"a basket or a tub, five pairs of rolled socks","6-8":"a basket, socks, a sheet of paper","9-12":"a basket, socks, a sheet of paper"},"steps":{"3-5":["Put the basket two steps away.","Your child throws five socks.","Count the hits out loud.","Take one step back and repeat."],"6-8":["Mark three lines: near, middle, far.","A hit from each is worth 1, 2 and 3 points.","Six throws each. You choose your own line.","Add up the points. Which line pays off best?"],"9-12":["Your child designs a tournament: rules, points, number of rounds.","One round is thrown with the weaker hand.","They keep the score table.","After the tournament, they change one rule to make it more fun."]}},{"id":"mover-8","scale":"mover","art":"🪞🙆🎵","title":"Mirror","why":"Copying someone else’s moves trains attention, coordination and movement memory.","tip":"Move slowly. The point is to be copied, not to trip them up.","need":{"3-5":"some free space","6-8":"some free space","9-12":"a timer, music"},"steps":{"3-5":["Stand facing your child.","Slowly raise an arm. They copy, like a mirror.","Add a bend, a step, a squat.","Now they lead and you’re the mirror."],"6-8":["Show a sequence of four moves.","Your child repeats it from memory.","They add a fifth move and you repeat the whole sequence.","Keep going until someone slips up."],"9-12":["Your child puts together a three-minute workout of six exercises.","Picks music for it.","Leads the workout for the family.","Asks which exercise to keep and which to replace."]}}],"safety":"Do the activities together. An adult handles scissors, knives and anything hot."};
